example.code:
try
{
    var container = await db.OpenOrCreateContainerAsync("products");
}
catch (ContainerNotFoundException ex)
{
    Console.WriteLine($"Container not found: {ex.ContainerName}");
}

try
{
    await container.PutDocumentAsync("events/evt-42.json", json,
        new DocumentOptions { Overwrite = false });
}
catch (DocumentExistsException ex)
{
    Console.WriteLine($"Duplicate: {ex.DocumentName} already exists in {ex.Container}");
}

try
{
    await using var txn = await db.BeginWriteAsync(TimeSpan.FromSeconds(5));
    // ... perform writes ...
    await txn.CommitAsync();
}
catch (TransactionTimeoutException ex)
{
    Console.WriteLine($"Write lock not acquired within {ex.Timeout}. Retrying...");
    // Implement retry logic here
}

try
{
    await foreach (var result in container.QueryAsync("//product[price >"))
    {
        Console.WriteLine(result);
    }
}
catch (XQueryException ex)
{
    Console.WriteLine($"Query error [{ex.ErrorCode}] at line {ex.Line}, column {ex.Column}");
    Console.WriteLine(ex.Message);
}

try
{
    await container.PutDocumentAsync("data.xml", malformedContent);
}
catch (DocumentParseException ex)
{
    Console.WriteLine($"Parse error in '{ex.DocumentName}' at line {ex.Line}, column {ex.Column}");
    Console.WriteLine(ex.Message);
}

para.code:
// Store a document
await container.PutDocumentAsync("orders/2024/order-001.xml", orderXml);

// Retrieve it
var doc = await container.GetDocumentAsync("orders/2024/order-001.xml");
var content = await doc!.GetContentAsync();

// Query with XQuery
await foreach (var result in container.QueryAsync("//order[total > 100]"))
{
    Console.WriteLine(result);
}

// List documents by prefix
await foreach (var info in container.ListDocumentsAsync("orders/2024/"))
{
    Console.WriteLine($"{info.Name} ({info.SizeBytes} bytes)");
}

example.code:
await container.PutDocumentAsync("events/evt-42.json",
    """{"type": "click", "timestamp": "2024-03-15T10:30:00Z"}""",
    new DocumentOptions
    {
        ContentType = ContentType.Json,
        Overwrite = false,
        Metadata = new Dictionary<XdmQName, XdmValue>
        {
            [new XdmQName(NamespaceId.PhoenixmlMeta, "source")] = XdmValue.From("web"),
            [new XdmQName(NamespaceId.PhoenixmlMeta, "priority")] = XdmValue.From(1L)
        }
    });

var doc = await container.GetDocumentAsync("orders/order-001.xml");
if (doc is not null)
{
    var xml = await doc.GetContentAsync();
    Console.WriteLine($"Document {doc.Name}, {doc.SizeBytes} bytes, type: {doc.ContentType}");
}

bool wasDeleted = await container.DeleteDocumentAsync("obsolete/old-report.xml");
if (!wasDeleted)
    Console.WriteLine("Document was already gone.");

await foreach (var info in container.ListDocumentsAsync())
{
    Console.WriteLine($"{info.Name} — {info.ContentType}, {info.SizeBytes} bytes");
}

// List all configuration documents
await foreach (var info in container.ListDocumentsAsync("config/"))
{
    Console.WriteLine(info.Name);
}

await foreach (var result in container.QueryAsync("collection()//product[price > 100]"))
{
    Console.WriteLine(result);
}

var variables = new Dictionary<string, object>
{
    ["minPrice"] = 50.0m,
    ["category"] = "electronics"
};
await foreach (var result in container.QueryAsync(
    """
    for $p in collection()//product
    where $p/price > $minPrice and $p/category = $category
    order by $p/price descending
    return $p/name
    """,
    variables))
{
    Console.WriteLine(result);
}

// everything received on or after the cutoff
await foreach (var d in container.QueryMetadataRangeAsync(Received, lowerBound: cutoff, upperBound: null))
    Console.WriteLine(d.Name);

var container = await db.CreateContainerAsync("products", opts =>
{
    // Index product IDs for fast lookup
    opts.Indexes
        .AddPathIndex("//product/@id")
        .AddValueIndex("//product/price", XdmValueType.XdmDecimal)
        .AddFullTextIndex("//product/description")
        .AddMetadataIndex("category", XdmValueType.XdmString);

    // Register namespaces so queries don't need to declare them
    opts.DefaultNamespaces.Add("p", "http://example.com/products");

    // Validate all incoming documents
    opts.ValidationMode = ValidationMode.WellFormed;
});

var options = new DocumentOptions
{
    ContentType = ContentType.Xml,
    Overwrite = false,
    Metadata = new Dictionary<string, object>
    {
        ["author"] = "Jane Smith",
        ["department"] = "Engineering"
    }
};
await container.PutDocumentAsync("reports/q1-2024.xml", xmlContent, options);

var doc = await container.GetDocumentAsync("orders/order-001.xml");
if (doc is not null)
{
    // Access raw content
    string xml = await doc.GetContentAsync();

    // Access parsed XDM tree
    var root = await doc.GetRootNodeAsync();
    Console.WriteLine($"Root element: {root.NodeName}");

    // Read metadata
    var status = await doc.GetMetadataAsync(Routing.Status.QName);
    Console.WriteLine($"Document {doc.Name}, status={status}, size={doc.SizeBytes} bytes");
}

var doc = await container.GetDocumentAsync("catalog.xml");
var root = await doc!.GetRootNodeAsync();

// root is the document node; its string value is all text content
Console.WriteLine($"Node kind: {root.NodeKind}");   // Document
Console.WriteLine($"Text content: {root.StringValue}");

var name = new QName(NamespaceId.None, "product");
Console.WriteLine(name.LocalName);    // "product"
Console.WriteLine(name.PrefixedName); // "product"

var nsName = new QName(NamespaceId.Xsd, "string", "xs");
Console.WriteLine(nsName.PrefixedName); // "xs:string"

para.code:
await using var db = await DocumentDatabase.OpenAsync("/path/to/db");
var container = await db.OpenOrCreateContainerAsync("products", opts =>
    opts.Indexes.AddPathIndex("//product/name")
                .AddValueIndex("//product/price", XdmValueType.XdmDecimal));
await container.PutDocumentAsync("item1.xml", xmlContent);

example.code:
var products = await db.CreateContainerAsync("products", opts =>
{
    opts.Indexes
        .AddPathIndex("//product/@id")
        .AddValueIndex("//product/price", XdmValueType.XdmDecimal)
        .AddFullTextIndex("//product/description");
    opts.DefaultNamespaces.Add("p", "http://example.com/products");
});

var container = await db.CreateContainerAsync("products", opts =>
{
    opts.Indexes
        // Fast lookup by element name across all namespaces
        .AddNameIndex()
        // Accelerate path-based queries
        .AddPathIndex("//product/@id")
        .AddPathIndex("//product/category")
        // Typed range queries on price and date
        .AddValueIndex("//product/price", XdmValueType.XdmDecimal)
        .AddValueIndex("//product/releaseDate", XdmValueType.Date)
        // Full-text search on descriptions
        .AddFullTextIndex("//product/description", new FullTextIndexOptions
        {
            Language = "en",
            Stemming = true,
            CaseSensitive = false
        })
        // Query documents by metadata (qualified — see AddMetadataIndex)
        .AddMetadataIndex(new XdmQName(CatalogNs, "supplier"), XdmValueType.XdmString)
        .AddMetadataIndex(new XdmQName(CatalogNs, "importBatch"), XdmValueType.XdmInteger);
});

remarks.para:
A name index accelerates queries that look up elements or attributes by name, such as
//product or //@id. Without a name index, the query engine must scan
every node in every document to find matching names.

When NOT to use: For single document reads or single queries, the convenience
methods on  (e.g., ,
) handle transactions automatically and are simpler.

example.code:
using var txn = db.BeginRead();
var customer = await txn.GetDocumentAsync(customersContainer.Id, "acme.xml");
var orders = txn.ListDocumentsAsync(ordersContainer.Id);

// Both reads see the same snapshot — no concurrent writes are visible
await foreach (var order in orders)
{
    Console.WriteLine($"Order: {order.Name}");
}

await using var txn = await db.BeginWriteAsync(TimeSpan.FromSeconds(10));
try
{
    foreach (var file in Directory.GetFiles("/data/imports/", "*.xml"))
    {
        var content = await File.ReadAllTextAsync(file);
        var name = $"imports/{Path.GetFileName(file)}";
        await txn.PutDocumentAsync(container.Id, name, content);
    }

    await txn.CommitAsync();
    Console.WriteLine("Import committed successfully.");
}
catch (Exception ex)
{
    await txn.RollbackAsync();
    Console.WriteLine($"Import rolled back: {ex.Message}");
}

